#include <iostream>
#include <chrono>
#include <thread>

class Game {
public:
    bool running = true;

    void processInput() {
        std::cout << "Checking for keyboard/mouse input...\n";
    }

    void update(float deltaTime) {
        std::cout << "Updating game world (" << deltaTime << "s passed)\n";
    }

    void render() {
        std::cout << "Drawing frame to screen\n";
    }

    void run() {
        auto previousTime = std::chrono::high_resolution_clock::now();

        while (running) {
            auto currentTime = std::chrono::high_resolution_clock::now();
            float deltaTime = std::chrono::duration<float>(currentTime - previousTime).count();
            previousTime = currentTime;

            processInput();
            update(deltaTime);
            render();

            std::this_thread::sleep_for(std::chrono::milliseconds(16));
        }
    }
};

int main() {
    Game game;
    game.run();
    return 0;
}

#include <cmath>

struct Vector3 {
    float x, y, z;

    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}

    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }

    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }

    float dot(const Vector3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    Vector3 cross(const Vector3& other) const {
        return Vector3(
            y * other.z - z * other.y,
            z * other.x - x * other.z,
            x * other.y - y * other.x
        );
    }

    float length() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vector3 normalize() const {
        float len = length();
        if (len > 0) return *this * (1.0f / len);
        return *this;
    }
};

struct Transform {
    Vector3 position;
    Vector3 rotation;
    Vector3 scale;

    void moveForward(float speed, float deltaTime) {
        position.z -= speed * deltaTime;
    }

    void moveRight(float speed, float deltaTime) {
        position.x += speed * deltaTime;
    }
};

