using EntityID = uint32_t;
using ComponentType = uint32_t;

// Base Component
struct Component {
    virtual ~Component() = default;
};

// Concrete Components
struct Position : Component {
    float x = 0, y = 0;
    Position(float x = 0, float y = 0) : x(x), y(y) {}
};

struct Velocity : Component {
    float vx = 0, vy = 0;
    Velocity(float vx = 0, float vy = 0) : vx(vx), vy(vy) {}
};

struct Health : Component {
    int hp = 100;
    int maxHp = 100;
    Health(int hp = 100) : hp(hp), maxHp(hp) {}
};

struct Renderable : Component {
    char symbol = '?';
    Renderable(char s = '?') : symbol(s) {}
};

// The Entity Manager
class EntityManager {
    EntityID nextId = 0;
    std::unordered_map<EntityID, std::unordered_map<ComponentType, std::unique_ptr<Component>>> entities;

public:
    EntityID createEntity() {
        EntityID id = nextId++;
        entities[id] = {};
        return id;
    }

    template<typename T, typename... Args>
    void addComponent(EntityID entity, Args&&... args) {
        entities[entity][getComponentType<T>()] = std::make_unique<T>(std::forward<Args>(args)...);
    }

    template<typename T>
    T* getComponent(EntityID entity) {
        auto& components = entities[entity];
        auto it = components.find(getComponentType<T>());
        if (it != components.end()) {
            return static_cast<T*>(it->second.get());
        }
        return nullptr;
    }

    template<typename T>
    std::vector<EntityID> getAllWith() {
        std::vector<EntityID> result;
        for (auto& [id, components] : entities) {
            if (components.count(getComponentType<T>())) {
                result.push_back(id);
            }
        }
        return result;
    }

private:
    template<typename T>
    static ComponentType getComponentType() {
        static ComponentType type = nextComponentType++;
        return type;
    }
    static ComponentType nextComponentType;
};
ComponentType EntityManager::nextComponentType = 0;

// Systems
void movementSystem(EntityManager& em, float dt) {
    for (auto id : em.getAllWith<Velocity>()) {
        auto* pos = em.getComponent<Position>(id);
        auto* vel = em.getComponent<Velocity>(id);
        if (pos && vel) {
            pos->x += vel->vx * dt;
            pos->y += vel->vy * dt;
        }
    }
}

void renderSystem(EntityManager& em) {
    for (auto id : em.getAllWith<Renderable>()) {
        auto* pos = em.getComponent<Position>(id);
        auto* ren = em.getComponent<Renderable>(id);
        if (pos && ren) {
            std::cout << ren->symbol << " at (" << pos->x << ", " << pos->y << ")\n";
        }
    }
}

int main() {
    EntityManager em;

    auto player = em.createEntity();
    em.addComponent<Position>(player, 0, 0);
    em.addComponent<Velocity>(player, 5, 3);
    em.addComponent<Renderable>(player, '@');
    em.addComponent<Health>(player);

    auto enemy = em.createEntity();
    em.addComponent<Position>(enemy, 100, 100);
    em.addComponent<Velocity>(enemy, -2, -1);
    em.addComponent<Renderable>(enemy, 'E');

    for (int frame = 0; frame < 5; ++frame) {
        std::cout << "Frame " << frame << ":\n";
        movementSystem(em, 0.016f);
        renderSystem(em);
        std::cout << "\n";
    }
    return 0;
}

using UnityEngine;

public class PlayerController : MonoBehaviour
{
    [Header("Movement Settings")]
    public float walkSpeed = 5f;
    public float sprintSpeed = 10f;
    public float jumpForce = 5f;
    public float mouseSensitivity = 2f;

    [Header("References")]
    public Camera playerCamera;
    public Transform groundCheck;
    public float groundDistance = 0.4f;
    public LayerMask groundMask;

    private Rigidbody rb;
    private float xRotation = 0f;
    private bool isGrounded;
    private Vector3 velocity;
    private float currentSpeed;

    void Awake()
    {
        rb = GetComponent<Rigidbody>();
        Cursor.lockState = CursorLockMode.Locked;
    }

    void Update()
    {
        // Mouse look
        float mouseX = Input.GetAxis("Mouse X") * mouseSensitivity;
        float mouseY = Input.GetAxis("Mouse Y") * mouseSensitivity;

        xRotation -= mouseY;
        xRotation = Mathf.Clamp(xRotation, -90f, 90f);

        playerCamera.transform.localRotation = Quaternion.Euler(xRotation, 0f, 0f);
        transform.Rotate(Vector3.up * mouseX);

        // Jump
        isGrounded = Physics.CheckSphere(groundCheck.position, groundDistance, groundMask);

        if (Input.GetButtonDown("Jump") && isGrounded)
        {
            velocity.y = Mathf.Sqrt(jumpForce * -2f * Physics.gravity.y);
        }
    }

    void FixedUpdate()
    {
        // Movement (in FixedUpdate for physics consistency)
        float x = Input.GetAxis("Horizontal");
        float z = Input.GetAxis("Vertical");

        Vector3 move = transform.right * x + transform.forward * z;
        currentSpeed = Input.GetKey(KeyCode.LeftShift) ? sprintSpeed : walkSpeed;

        Vector3 targetVelocity = move * currentSpeed;
        targetVelocity.y = rb.velocity.y;
        rb.velocity = targetVelocity;
    }

    public void TakeDamage(int damage)
    {
        // Called by enemy bullets, traps, etc.
        Debug.Log($"Player took {damage} damage!");
    }
}

using UnityEngine;

public class Weapon : MonoBehaviour
{
    [Header("Weapon Stats")]
    public string weaponName = "Pistol";
    public float fireRate = 0.5f;
    public int maxAmmo = 12;
    public float reloadTime = 1.5f;
    public float damage = 25f;
    public float range = 100f;

    [Header("References")]
    public Transform firePoint;
    public GameObject bulletPrefab;
    public ParticleSystem muzzleFlash;
    public AudioClip shootSound;

    private int currentAmmo;
    private float nextFireTime = 0f;
    private bool isReloading = false;
    private AudioSource audioSource;

    void Awake()
    {
        currentAmmo = maxAmmo;
        audioSource = GetComponent<AudioSource>();
    }

    void Update()
    {
        if (isReloading) return;

        if (currentAmmo <= 0 && Input.GetButtonDown("Fire1"))
        {
            StartCoroutine(Reload());
            return;
        }

        if (Input.GetButtonDown("Fire1") && Time.time >= nextFireTime)
        {
            nextFireTime = Time.time + fireRate;
            Shoot();
        }

        if (Input.GetKeyDown(KeyCode.R))
        {
            StartCoroutine(Reload());
        }
    }

    void Shoot()
    {
        currentAmmo--;

        // Visual effects
        if (muzzleFlash) muzzleFlash.Play();
        if (shootSound && audioSource) audioSource.PlayOneShot(shootSound);

        // Create bullet
        GameObject bullet = Instantiate(bulletPrefab, firePoint.position, firePoint.rotation);

        // Raycast for hit detection
        RaycastHit hit;
        if (Physics.Raycast(firePoint.position, firePoint.forward, out hit, range))
        {
            var target = hit.transform.GetComponent<IDamageable>();
            if (target != null)
            {
                target.TakeDamage(damage);
            }

            // Spawn impact effect
            Debug.Log($"Hit {hit.transform.name} at {hit.point}");
        }
    }

    System.Collections.IEnumerator Reload()
    {
        isReloading = true;
        Debug.Log($"Reloading {weaponName}...");
        yield return new WaitForSeconds(reloadTime);
        currentAmmo = maxAmmo;
        isReloading = false;
    }
}

