using UnityEngine;
using UnityEngine.SceneManagement;

public class GameManager : MonoBehaviour
{
    public static GameManager Instance { get; private set; }

    [Header("Game State")]
    public int currentLevel = 1;
    public int playerScore = 0;
    public int playerLives = 3;
    public float gameTime = 0f;

    [Header("Settings")]
    public bool isPaused = false;

    private void Awake()
    {
        // Singleton pattern - only one GameManager exists
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject); // Persist across scenes
    }

    private void Update()
    {
        if (!isPaused)
            gameTime += Time.deltaTime;

        if (Input.GetKeyDown(KeyCode.Escape))
            TogglePause();
    }

    public void AddScore(int points)
    {
        playerScore += points;
        UIManager.Instance.UpdateScoreDisplay(playerScore);
    }

    public void PlayerDied()
    {
        playerLives--;
        if (playerLives <= 0)
            GameOver();
        else
            RespawnPlayer();
    }

    void GameOver()
    {
        Debug.Log("Game Over! Final Score: " + playerScore);
        SceneManager.LoadScene("GameOver");
    }

    void RespawnPlayer()
    {
        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
    }

    public void TogglePause()
    {
        isPaused = !isPaused;
        Time.timeScale = isPaused ? 0f : 1f;
    }
}

// Vertex shader input
struct VertexInput {
    float3 position : POSITION;
    float3 normal : NORMAL;
    float2 uv : TEXCOORD0;
};

// Vertex shader output / Pixel shader input
struct VertexOutput {
    float4 position : SV_POSITION;
    float3 worldNormal : TEXCOORD0;
    float2 uv : TEXCOORD1;
    float3 worldPos : TEXCOORD2;
};

// Constant buffer (like a uniform in GLSL)
cbuffer PerFrame : register(b0) {
    float4x4 worldMatrix;
    float4x4 viewProjectionMatrix;
    float4 lightDirection;
    float4 lightColor;
    float4 ambientColor;
};

VertexOutput vs_main(VertexInput input) {
    VertexOutput output;

    // Transform position to world space
    float4 worldPos = mul(float4(input.position, 1.0), worldMatrix);
    output.position = mul(worldPos, viewProjectionMatrix);
    output.worldPos = worldPos.xyz;

    // Transform normal to world space
    output.worldNormal = normalize(mul(input.normal, (float3x3)worldMatrix));
    output.uv = input.uv;

    return output;
}

float4 ps_main(VertexOutput input) : SV_TARGET {
    // Simple diffuse lighting
    float3 normal = normalize(input.worldNormal);
    float3 lightDir = normalize(-lightDirection.xyz);

    float NdotL = max(0.0, dot(normal, lightDir));

    float3 diffuse = lightColor.rgb * NdotL;
    float3 finalColor = ambientColor.rgb + diffuse;

    return float4(finalColor, 1.0);
}

