Shader "Custom/PBRStandard"
{
    Properties
    {
        _MainTex ("Albedo (RGB)", 2D) = "white" {}
        _Metallic ("Metallic", Range(0,1)) = 0.0
        _Smoothness ("Smoothness", Range(0,1)) = 0.5
    }

    SubShader
    {
        Tags { "RenderType"="Opaque" }

        CGPROGRAM
        #pragma surface surf Standard fullforwardshadows
        #pragma target 3.0

        sampler2D _MainTex;
        half _Metallic;
        half _Smoothness;

        struct Input
        {
            float2 uv_MainTex;
        };

        void surf(Input IN, inout SurfaceOutputStandard o)
        {
            fixed4 c = tex2D(_MainTex, IN.uv_MainTex);
            o.Albedo = c.rgb;
            o.Metallic = _Metallic;
            o.Smoothness = _Smoothness;
            o.Alpha = c.a;
        }
        ENDCG
    }
    FallBack "Diffuse"
}

#version 450 core

// GLSL Compute Shader for particle simulation
// This runs on the GPU in parallel for thousands of particles

layout(local_size_x = 256, local_size_y = 1, local_size_z = 1) in;

struct Particle {
    vec3 position;
    vec3 velocity;
    vec4 color;
    float lifetime;
    float maxLifetime;
    float size;
};

layout(std430, binding = 0) buffer ParticleBuffer {
    Particle particles[];
};

layout(std140, binding = 1) uniform SimParams {
    vec3 gravity;
    float deltaTime;
    vec3 emitterPosition;
    float spawnRate;
    uint particleCount;
    float time;
};

void main() {
    uint index = gl_GlobalInvocationID.x;
    if (index >= particleCount) return;

    Particle p = particles[index];

    // Update lifetime
    p.lifetime -= deltaTime;

    if (p.lifetime <= 0.0) {
        // Respawn particle at emitter
        p.position = emitterPosition;
        p.velocity = vec3(
            (float(gl_GlobalInvocationID.x & 0xFF) / 255.0 - 0.5) * 10.0,
            5.0 + (float((gl_GlobalInvocationID.x >> 8) & 0xFF) / 255.0) * 5.0,
            (float((gl_GlobalInvocationID.x >> 16) & 0xFF) / 255.0 - 0.5) * 10.0
        );
        p.lifetime = p.maxLifetime;
        p.color = vec4(1.0, 0.5, 0.0, 1.0);
    } else {
        // Apply physics
        p.velocity += gravity * deltaTime;
        p.position += p.velocity * deltaTime;

        // Fade out as particle ages
        float age = 1.0 - (p.lifetime / p.maxLifetime);
        p.color.a = 1.0 - age;
        p.size = 1.0 + age * 2.0;
    }

    particles[index] = p;
}

