// Systems (logic)
fn player_movement(
    keyboard: Res<Input<KeyCode>>,
    mut query: Query<(&Player, &mut Position)>,
    time: Res<Time>,
) {
    for (player, mut position) in query.iter_mut() {
        let mut dx = 0.0;
        let mut dy = 0.0;

        if keyboard.pressed(KeyCode::W) { dy += 1.0; }
        if keyboard.pressed(KeyCode::S) { dy -= 1.0; }
        if keyboard.pressed(KeyCode::A) { dx -= 1.0; }
        if keyboard.pressed(KeyCode::D) { dx += 1.0; }

        // Normalize diagonal movement
        if dx != 0.0 && dy != 0.0 {
            let inv = std::f32::consts::FRAC_1_SQRT_2;
            dx *= inv;
            dy *= inv;
        }

        position.x += dx * player.speed * time.delta_seconds();
        position.y += dy * player.speed * time.delta_seconds();
    }
}

fn main() {
    App::new()
        .add_plugins(DefaultPlugins)
        .add_system(player_movement)
        .add_startup_system(setup)
        .run();
}

