#include <cmath>
#include <array>

struct Vector3 {
    float x, y, z;

    Vector3() : x(0), y(0), z(0) {}
    Vector3(float x, float y, float z) : x(x), y(y), z(z) {}

    // Basic operations
    Vector3 operator+(const Vector3& v) const { return {x+v.x, y+v.y, z+v.z}; }
    Vector3 operator-(const Vector3& v) const { return {x-v.x, y-v.y, z-v.z}; }
    Vector3 operator*(float s) const { return {x*s, y*s, z*s}; }
    Vector3 operator/(float s) const { return {x/s, y/s, z/s}; }

    // Dot product: tells how much two vectors point in the same direction
    // Returns 1 if same direction, 0 if perpendicular, -1 if opposite
    float dot(const Vector3& v) const {
        return x*v.x + y*v.y + z*v.z;
    }

    // Cross product: gives a vector perpendicular to both inputs
    // Used for finding "up" from "forward" and "right"
    Vector3 cross(const Vector3& v) const {
        return {
            y*v.z - z*v.y,
            z*v.x - x*v.z,
            x*v.y - y*v.x
        };
    }

    float length() const { return std::sqrt(x*x + y*y + z*z); }
    float lengthSquared() const { return x*x + y*y + z*z; }

    Vector3 normalize() const {
        float len = length();
        if (len < 0.0001f) return {0,0,0};
        return *this / len;
    }

    // Linear interpolation: smoothly move from A to B by t (0..1)
    static Vector3 lerp(const Vector3& a, const Vector3& b, float t) {
        return a + (b - a) * t;
    }
};

// 4x4 Matrix for 3D transformations
struct Matrix4x4 {
    std::array<float, 16> m; // Column-major

    Matrix4x4() {
        m.fill(0);
        m[0] = m[5] = m[10] = m[15] = 1; // Identity
    }

    static Matrix4x4 translation(float x, float y, float z) {
        Matrix4x4 mat;
        mat.m[12] = x;
        mat.m[13] = y;
        mat.m[14] = z;
        return mat;
    }

    static Matrix4x4 rotationX(float angle) {
        Matrix4x4 mat;
        float c = std::cos(angle), s = std::sin(angle);
        mat.m[5] = c;   mat.m[6] = s;
        mat.m[9] = -s;  mat.m[10] = c;
        return mat;
    }

    static Matrix4x4 rotationY(float angle) {
        Matrix4x4 mat;
        float c = std::cos(angle), s = std::sin(angle);
        mat.m[0] = c;   mat.m[2] = -s;
        mat.m[8] = s;   mat.m[10] = c;
        return mat;
    }

    static Matrix4x4 scale(float sx, float sy, float sz) {
        Matrix4x4 mat;
        mat.m[0] = sx;
        mat.m[5] = sy;
        mat.m[10] = sz;
        return mat;
    }

    Matrix4x4 operator*(const Matrix4x4& other) const {
        Matrix4x4 result;
        for (int row = 0; row < 4; ++row) {
            for (int col = 0; col < 4; ++col) {
                result.m[col*4+row] = 0;
                for (int k = 0; k < 4; ++k) {
                    result.m[col*4+row] += m[k*4+row] * other.m[col*4+k];
                }
            }
        }
        return result;
    }

    Vector3 transform(const Vector3& v) const {
        return {
            m[0]*v.x + m[4]*v.y + m[8]*v.z + m[12],
            m[1]*v.x + m[5]*v.y + m[9]*v.z + m[13],
            m[2]*v.x + m[6]*v.y + m[10]*v.z + m[14]
        };
    }
};

// Quaternion: represents rotation without gimbal lock
// Think of it as a rotation around an axis (x,y,z) by angle w
struct Quaternion {
    float x, y, z, w;

    Quaternion() : x(0), y(0), z(0), w(1) {}
    Quaternion(float x, float y, float z, float w) : x(x), y(y), z(z), w(w) {}

    // Create quaternion from axis-angle
    static Quaternion fromAxisAngle(const Vector3& axis, float angle) {
        float halfAngle = angle * 0.5f;
        float s = std::sin(halfAngle);
        Vector3 n = axis.normalize();
        return {n.x*s, n.y*s, n.z*s, std::cos(halfAngle)};
    }

    Quaternion operator*(const Quaternion& q) const {
        return {
            w*q.x + x*q.w + y*q.z - z*q.y,
            w*q.y - x*q.z + y*q.w + z*q.x,
            w*q.z + x*q.y - y*q.x + z*q.w,
            w*q.w - x*q.x - y*q.y - z*q.z
        };
    }

    Vector3 rotate(const Vector3& v) const {
        Quaternion p(v.x, v.y, v.z, 0);
        Quaternion qConj(-x, -y, -z, w);
        Quaternion result = *this * p * qConj;
        return {result.x, result.y, result.z};
    }

    // Spherical linear interpolation: smooth rotation between two orientations
    static Quaternion slerp(const Quaternion& a, const Quaternion& b, float t) {
        float cosAngle = a.x*b.x + a.y*b.y + a.z*b.z + a.w*b.w;
        Quaternion b2 = b;
        if (cosAngle < 0) { cosAngle = -cosAngle; b2 = {-b.x, -b.y, -b.z, -b.w}; }

        float angle = std::acos(cosAngle);
        float s1 = std::sin((1-t)*angle) / std::sin(angle);
        float s2 = std::sin(t*angle) / std::sin(angle);

        return {a.x*s1+b2.x*s2, a.y*s1+b2.y*s2, a.z*s1+b2.z*s2, a.w*s1+b2.w*s2};
    }
};

// Usage example
int main() {
    // Create a player transform
    Matrix4x4 world = Matrix4x4::translation(10, 0, 5) * Matrix4x4::rotationY(3.14159f/4);

    // Convert local to world direction
    Vector3 localForward(0, 0, -1);
    Vector3 worldForward = world.transform(localForward);

    // Smooth rotation with quaternion lerp
    Quaternion current = Quaternion::fromAxisAngle({0,1,0}, 0);
    Quaternion target = Quaternion::fromAxisAngle({0,1,0}, 3.14159f/2);
    Quaternion smoothed = Quaternion::slerp(current, target, 0.5f);

    return 0;
}

#include <memory>
#include <iostream>

// Forward declare
class Player;

// Base State class
class PlayerState {
public:
    virtual ~PlayerState() = default;
    virtual void enter(Player& player) = 0;
    virtual void update(Player& player, float deltaTime) = 0;
    virtual void exit(Player& player) = 0;
    virtual std::string getName() const = 0;
};

// The Player (Context)
class Player {
    std::unique_ptr<PlayerState> currentState;

public:
    float health = 100;
    float stamina = 100;
    float verticalVelocity = 0;
    bool isGrounded = true;
    int attackCombo = 0;
    float comboTime = 0;

    void setState(std::unique_ptr<PlayerState> newState) {
        if (currentState) currentState->exit(*this);
        currentState = std::move(newState);
        currentState->enter(*this);
    }

    void update(float dt) {
        currentState->update(*this, dt);
    }

    std::string getStateName() const {
        return currentState ? currentState->getName() : "None";
    }
};

// Concrete States
