    std::string getName() const override { return "Walk"; }
};

class JumpState : public PlayerState {
public:
    void enter(Player& p) override {
        std::cout << "Entering Jump state\n";
        p.verticalVelocity = 10; // Jump impulse
        p.isGrounded = false;
    }
    void update(Player& p, float dt) override {
        p.verticalVelocity -= 9.81f * dt; // Gravity

        if (p.verticalVelocity < 0 && p.isGrounded) {
            p.setState(std::make_unique<IdleState>());
        }
    }
    void exit(Player& p) override {
        p.verticalVelocity = 0;
    }
    std::string getName() const override { return "Jump"; }
};

class AttackState : public PlayerState {
public:
    void enter(Player& p) override {
        std::cout << "Entering Attack state (combo: " << p.attackCombo << ")\n";
        p.comboTime = 0.5f;
    }
    void update(Player& p, float dt) override {
        p.comboTime -= dt;

        // Check for next combo input
        // if (attackPressed && comboTime > 0) -> next combo

        if (p.comboTime <= 0) {
            p.attackCombo = 0;
            p.setState(std::make_unique<IdleState>());
        }
    }
    void exit(Player& p) override {}
    std::string getName() const override { return "Attack"; }
};

