#include <vector>
#include <functional>
#include <unordered_map>
#include <any>
#include <iostream>

// Event types
enum class EventType {
    ENEMY_DIED,
    PLAYER_DIED,
    SCORE_CHANGED,
    ITEM_COLLECTED,
    LEVEL_COMPLETE
};

struct Event {
    EventType type;
    std::unordered_map<std::string, std::any> data;

    Event(EventType type) : type(type) {}

    template<typename T>
    T get(const std::string& key, const T& defaultValue = T()) const {
        auto it = data.find(key);
        if (it != data.end() && it->second.has_value()) {
            try { return std::any_cast<T>(it->second); }
            catch(...) {}
        }
        return defaultValue;
    }
};

// The Event System (Observer Pattern)
class EventBus {
    using Callback = std::function<void(const Event&)>;
    std::unordered_map<EventType, std::vector<Callback>> listeners;

public:
    void subscribe(EventType type, Callback callback) {
        listeners[type].push_back(callback);
    }

    void publish(const Event& event) {
        auto it = listeners.find(event.type);
        if (it != listeners.end()) {
            for (auto& callback : it->second) {
                callback(event);
            }
        }
    }
};

// Usage example
int main() {
    EventBus eventBus;

    // Subscribe to events
    eventBus.subscribe(EventType::ENEMY_DIED, [](const Event& e) {
        int score = e.get<int>("score", 0);
        std::string enemyType = e.get<std::string>("type", "unknown");
        std::cout << "Enemy died! +" << score << " points (" << enemyType << ")\n";
    });

    eventBus.subscribe(EventType::PLAYER_DIED, [](const Event& e) {
        std::cout << "Player died! Game Over.\n";
    });

    eventBus.subscribe(EventType::SCORE_CHANGED, [](const Event& e) {
        int newScore = e.get<int>("score", 0);
        std::cout << "Score updated: " << newScore << "\n";
    });

    // Fire events
    Event enemyEvent(EventType::ENEMY_DIED);
    enemyEvent.data["score"] = 100;
    enemyEvent.data["type"] = std::string("Goblin");
    eventBus.publish(enemyEvent);

    Event scoreEvent(EventType::SCORE_CHANGED);
    scoreEvent.data["score"] = 150;
    eventBus.publish(scoreEvent);

    return 0;
}
